// Fork of "VT + Acute Angle Detection" by Chimel. https://shadertoy.com/view/MXyfzh
// 2025-01-26 19:16:16

// Fork of "Basic : Voronoi Tracking" by Gijs. https://shadertoy.com/view/WltSz7


// --------------------------------------------------------
// IMAGE (FINAL PASS)
// --------------------------------------------------------
// iChannel0 => Buffer A  (positions/vel)
// iChannel1 => Buffer B  (4 nearest site IDs per pixel, Minkowski-based)
// iChannel2 => Buffer C  (stores Minkowski-based distance to nearest neighbor)
// iChannel3 => Buffer D  (stores each site's radius in .r)

#define VERTEX_RADIUS 1.5  // highlight size for corners

//-----------------------------------
// HELPER FUNCTIONS
//-----------------------------------

ivec2 locFromID(int id)
{
    int w = int(iResolution.x);
    return ivec2(id % w, id / w);
}

vec4 getParticle(int id)
{
    return texelFetch(iChannel0, locFromID(id), 0);
}

float getRadius(int id)
{
    return texelFetch(iChannel3, locFromID(id), 0).r;
}

// Periodic distance
float periodicDist(vec2 a, vec2 b)
{
    vec2 d = a - b;
    d = mod(d + 0.5*iResolution.xy, iResolution.xy) - 0.5*iResolution.xy;
    return length(d);
}

// Periodic delta
vec2 periodicDelta(vec2 delta)
{
    return mod(delta + 0.5*iResolution.xy, iResolution.xy) - 0.5*iResolution.xy;
}

// For a pixel c, gather 4 candidate IDs from Buffer B
ivec4 getClosest4(ivec2 c)
{
    // wrap
    ivec2 res = ivec2(iResolution.xy);
    c = ivec2((c.x + res.x) % res.x, (c.y + res.y) % res.y);
    return ivec4(texelFetch(iChannel1, c, 0));
}

// (distance - radius) measure for Minkowski offset
float getMeasure(vec2 P, int siteID)
{
    vec2 center = getParticle(siteID).xy;
    float rad   = getRadius(siteID);
    float dist  = periodicDist(P, center);
    return dist - rad;
}

// Pick the site with the minimal (dist - radius)
int getNearestID(ivec2 c)
{
    ivec4 four = getClosest4(c);
    float bestVal = 1e20;
    int   bestID  = -1;
    vec2  fc      = vec2(c);

    for (int i=0; i<4; i++)
    {
        int candidateID = four[i];
        if (candidateID < 0) continue;

        float val = getMeasure(fc, candidateID);
        if (val < bestVal)
        {
            bestVal = val;
            bestID  = candidateID;
        }
    }
    return bestID;
}

// Count distinct sites in a 3x3 block (corner detection).
int countDistinctSites(ivec2 center)
{
    int arr[9];
    int index = 0;
    for(int dy=-1; dy<=1; dy++){
        for(int dx=-1; dx<=1; dx++){
            ivec2 c = center + ivec2(dx, dy);
            c = clamp(c, ivec2(0), ivec2(iResolution.xy)-ivec2(1));
            arr[index++] = getNearestID(c);
        }
    }

    int distinct = 0;
    for(int i=0; i<9; i++){
        bool isNew = true;
        for(int j=0; j<i; j++){
            if(arr[i] == arr[j]){
                isNew = false;
                break;
            }
        }
        if(isNew) distinct++;
    }
    return distinct;
}

// Simple random grey function
float randomGrey(int siteID)
{
    float r = fract(sin(float(siteID) * 78.233) * 43758.5453);
    return 0.85 + 0.1 * r;
}

//-----------------------------------
// MAIN
//-----------------------------------
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    //------------------------------------
    // 1) Find nearest site ID for this pixel
    //------------------------------------
    ivec2 pc  = ivec2(fragCoord);
    int   sid = getNearestID(pc);

    //------------------------------------
    // 2) Base color: random grey
    //------------------------------------
    float grey = randomGrey(sid);
    vec4 baseLayer = vec4(vec3(grey), 1.0);

    //------------------------------------
    // 3) "secondDist" from Buffer C 
    //    (the Minkowski-based distance to nearest neighbor site)
    //------------------------------------
    float secondDist = texelFetch(iChannel2, locFromID(sid), 0).x;

    //------------------------------------
    // 4) Blue tint based on cell size
    //------------------------------------
    float maxSize   = length(iResolution.xy) * 0.125;
    float sizeRatio = clamp(secondDist / maxSize, 0.0, 1.0);
    // As secondDist gets smaller => more blue. 
    vec4 blueLayer  = vec4(0.0, 0.0, 0.8, 0.8 * (1.0 - sizeRatio));
    vec4 color      = mix(baseLayer, blueLayer, blueLayer.a);

    //------------------------------------
    // 5) Partially transparent circle highlight
    //------------------------------------
    vec2 sitePos = getParticle(sid).xy;
    float siteRad= getRadius(sid);
    // distance minus radius from pixel
    float distToSite = periodicDist(fragCoord, sitePos);
    float dmr        = distToSite - siteRad;

    // "highlight" factor 0..1 (1 near the circle center)
    float highlight  = smoothstep(2.0, 0.0, dmr);

    float alpha = 1.0 * highlight;      // up to 30% opacity in the center
    vec3 circleColor = vec3(1.0);       // white circle

    // Blend the circle on top of the cell color
    color.rgb = mix(color.rgb, circleColor, alpha);

    //------------------------------------
    // 6) Light edge highlight 
    //------------------------------------
    float edge = smoothstep(0.0, 1.0, abs(dFdx(grey)) + abs(dFdy(grey)));
    color.rgb  = mix(color.rgb, vec3(1.0), edge);

    //------------------------------------
    // 7) Voronoi corner detection
    //------------------------------------
    int dCount = countDistinctSites(pc);
    if(dCount >= 3)
    {
        // We'll gather up to 3 distinct sites
        ivec4 c4 = getClosest4(pc);
        int ids[4] = int[4](c4[0], c4[1], c4[2], c4[3]);

        int uniqueIDs[3];
        int uniqCount = 0;
        for(int i=0; i<4 && uniqCount<3; i++)
        {
            bool isNew = true;
            for(int j=0; j<uniqCount; j++){
                if(ids[i] == uniqueIDs[j]){
                    isNew = false;
                    break;
                }
            }
            if(isNew){
                uniqueIDs[uniqCount++] = ids[i];
            }
        }
        if(uniqCount < 3)
        {
            fragColor = color;
            return;
        }

        int id0 = uniqueIDs[0];
        int id1 = uniqueIDs[1];
        int id2 = uniqueIDs[2];

        vec2 A = getParticle(id0).xy;
        vec2 B = getParticle(id1).xy;
        vec2 C = getParticle(id2).xy;

        // Periodic vectors
        vec2 AB = periodicDelta(B - A);
        vec2 AC = periodicDelta(C - A);
        vec2 BA = periodicDelta(A - B);
        vec2 BC = periodicDelta(C - B);
        vec2 CA = periodicDelta(A - C);
        vec2 CB = periodicDelta(B - C);

        bool obtuseA = dot(AB, AC) < 0.0;
        bool obtuseB = dot(BA, BC) < 0.0;
        bool obtuseC = dot(CA, CB) < 0.0;

        // The usual point-based corner calc (circumcenter or midpoint).
        vec2 vertexPos;
        if(!obtuseA && !obtuseB && !obtuseC)
        {
            // All angles acute => circumcenter
            vec2 midAB = A + 0.5*AB;
            vec2 midAC = A + 0.5*AC;
            vec2 dirAB = vec2(-AB.y, AB.x);
            vec2 dirAC = vec2(-AC.y, AC.x);

            mat2 M   = mat2(dirAB, -dirAC);
            vec2 rhs = midAC - midAB;
            float det = M[0][0]*M[1][1] - M[0][1]*M[1][0];
            if(abs(det) > 1e-4)
            {
                vec2 t = (1.0/det) * vec2(
                    M[1][1]*rhs.x - M[0][1]*rhs.y,
                    -M[1][0]*rhs.x + M[0][0]*rhs.y
                );
                vertexPos = midAB + t.x * dirAB;
            }
            else
            {
                vertexPos = (A + B + C) / 3.0;
            }
        }
        else
        {
            // There's an obtuse angle => midpoint of opposite side
            if(obtuseA){
                vertexPos = B + 0.5 * BC;
            } else if(obtuseB){
                vertexPos = A + 0.5 * AC;
            } else {
                vertexPos = A + 0.5 * AB;
            }
        }

        vertexPos = mod(vertexPos + 0.5*iResolution.xy, iResolution.xy) - 0.5*iResolution.xy;

        float vertexDist = periodicDist(fragCoord, vertexPos);
        if(vertexDist < VERTEX_RADIUS)
        {
            // If any angle obtuse => red, else green
            color.rgb = (obtuseA || obtuseB || obtuseC)
                        ? vec3(1.0, 0.0, 0.0) // RED
                        : vec3(0.0, 1.0, 0.0) // GREEN
                        ;
        }
    }

    // Final output color
    fragColor = color;
}

// --------------------------------------------------------
// COMMON TAB
// --------------------------------------------------------
const int PARTICLES = 500;
const float SPEED = 1.0;

// SINGLE DEFINITION - GLSL-compatible hash
float hash(int k) {
    uint n = uint(k) * 1597334677U; // Valid 32-bit prime
    n = (n << 13U) ^ n;
    n = n * (n * n * 15731U + 789221U) + 1376312589U;
    return uintBitsToFloat((n >> 9U) | 0x3f800000U) - 1.0;
}

// --------------------------------------------------------
// BUFFER A
// --------------------------------------------------------
// iChannel0 => Buffer A (backbuffer storing (pos, vel))
// iChannel1 => Buffer B (to find nearest neighbor IDs)
// iChannel2 => (unused)
// iChannel3 => Buffer D (radii)
//
// We assume in "Common" we have:
//   const int   PARTICLES = 1000;  // or 500
//   const float SPEED     = 1.0;
//   float hash(int k) { ... }   // etc.

//////////////////////////////////////
// Helper & Access Functions
//////////////////////////////////////

ivec2 locFromID(int id)
{
    int w = int(iResolution.x);
    return ivec2(id % w, id / w);
}

// Fetch (pos, vel) for a particle from this same buffer
vec4 getParticle(int id)
{
    return texelFetch(iChannel0, locFromID(id), 0);
}

// Fetch the 4 nearest neighbor IDs from Buffer B
ivec4 getClosest4(ivec2 coords)
{
    // Wrap or clamp coords as needed; here we do wrap:
    ivec2 res = ivec2(iResolution.xy);
    coords = ivec2((coords.x + res.x) % res.x, (coords.y + res.y) % res.y);
    return ivec4(texelFetch(iChannel1, coords, 0));
}

// Fetch the radius of a particle from Buffer D
float getRadius(int id)
{
    return texelFetch(iChannel3, locFromID(id), 0).r;
}

// Periodic delta to handle wrapping
vec2 periodicDelta(vec2 delta)
{
    // SHIFT by half-size, mod, SHIFT back
    return mod(delta + 0.5*iResolution.xy, iResolution.xy) - 0.5*iResolution.xy;
}

//////////////////////////////////////
// mainImage
//////////////////////////////////////

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 pix = ivec2(fragCoord);
    int   id  = pix.x + pix.y * int(iResolution.x);

    // If not a valid particle, just copy old data
    if(id >= PARTICLES)
    {
        fragColor = texelFetch(iChannel0, pix, 0);
        return;
    }

    // Load old pos & vel
    vec4 prev = texelFetch(iChannel0, pix, 0);
    vec2 pos  = prev.xy;
    vec2 vel  = prev.zw;

    // On first frame, initialize random position
    if(iFrame == 0)
    {
        float h1 = hash(id);
        float h2 = hash(id + 99999);
        pos = vec2(h1, h2) * iResolution.xy;
        vel = vec2(0.0);
    }

    //--------------------------------
    // 1) Accumulate forces
    //--------------------------------
    vec2 force = vec2(0.0);

    // (a) friction
    force -= vel * 0.3;

    // (b) mouse repulsion (if pressed)
    if(iMouse.z > 0.0)
    {
        vec2 delta = pos - iMouse.xy;
        float dist = length(delta) + 1e-3;
        // example 1/r^2 repulsion
        force += delta / (dist * dist) * 10.0;
    }

    // (c) neighbor repulsion with circle size awareness
    float radA = getRadius(id);

    // Get the 4 nearest IDs from Buffer B at integer coords near 'pos'
    ivec2 ipos = ivec2(floor(pos));
    ivec4 closeIDs = getClosest4(ipos);

    for(int i=0; i<4; i++)
    {
        int cid = closeIDs[i];
        if(cid < 0 || cid == id) continue;

        vec2  otherPos = getParticle(cid).xy;
        float radB     = getRadius(cid);

        // periodic distance
        vec2 delta = pos - otherPos;
        delta = periodicDelta(delta);
        float dist  = length(delta) + 1e-6;

        // baseline "point-based" repulsion at all distances
        float factor = 30.0 / (dist*dist*dist);
        force += delta * factor;

        // additional "soft-sphere" push if circles overlap
        float sumRad  = radA + radB;
        float overlap = sumRad - dist;
        if(overlap > 0.0)
        {
            // They overlap => push them apart more strongly
            float extra = 30.0 * overlap;
            force += normalize(delta) * extra;
        }
    }

    //--------------------------------
    // 2) Integrate & Wrap
    //--------------------------------
    vel += force;

    // Cap speed
    float spd = length(vel);
    if(spd > SPEED)
    {
        vel *= (SPEED / spd);
    }

    // Move and wrap
    pos = mod(pos + vel, iResolution.xy);

    // Output the updated (pos, vel)
    fragColor = vec4(pos, vel);
}

// --------------------------------------------------------
// BUFFER B
// --------------------------------------------------------
// iChannel0 => Buffer A (positions/vel)
// iChannel1 => Buffer B (backbuffer)
// iChannel2 => (unused here)
// iChannel3 => Buffer D (radii) <--- (CHANGED) we fetch from D
//
// We rely on a hash(int k) function from the Common tab.

////////////////////////////////////
// HELPER FUNCTIONS
////////////////////////////////////

// Wrap neighbor coords for a periodic domain
ivec2 wrapCoords(ivec2 c) {
    ivec2 res = ivec2(iResolution.xy);
    return ivec2((c.x + res.x) % res.x, (c.y + res.y) % res.y);
}

// Convert site/particle ID -> pixel coords
ivec2 locFromID(int id) {
    int w = int(iResolution.x);
    return ivec2(id % w, id / w);
}

// Retrieve (pos, vel) from Buffer A for a given site ID
vec4 getParticle(int id) {
    return texelFetch(iChannel0, locFromID(id), 0);
}

// measure: distance minus radius
float measureParticle(int id, vec2 fragCoord) {
    if (id < 0) return 1e20;

    vec2 p    = getParticle(id).xy;
    float rad = texelFetch(iChannel3, locFromID(id), 0).r;

    // periodic distance
    vec2 d = p - fragCoord;
    d = mod(d + 0.5 * iResolution.xy, iResolution.xy) - 0.5 * iResolution.xy;
    float dist = length(d);

    return dist - rad;  // Minkowski offset
}

// Insertion sort that also updates duplicates if we find a smaller distance
void insertion_sort(inout ivec4 i, inout vec4 d, int newID, float newVal)
{
    // Check for existing entry
    for (int idx = 0; idx < 4; idx++) {
        if (i[idx] == newID) {
            // If newVal is smaller, bubble
            if (newVal < d[idx]) {
                d[idx] = newVal;
                for (int k = idx; k > 0 && d[k] < d[k-1]; k--) {
                    // swap
                    int tmpI = i[k];
                    i[k]     = i[k-1];
                    i[k-1]   = tmpI;

                    float tmpD = d[k];
                    d[k]       = d[k-1];
                    d[k-1]     = tmpD;
                }
            }
            return;
        }
    }

    // Normal insertion if not a duplicate
    if (newVal < d[0]) {
        i = ivec4(newID, i[0], i[1], i[2]);
        d = vec4(newVal, d[0], d[1], d[2]);
    } else if (newVal < d[1]) {
        i = ivec4(i[0], newID, i[1], i[2]);
        d = vec4(d[0], newVal, d[1], d[2]);
    } else if (newVal < d[2]) {
        i = ivec4(i[0], i[1], newID, i[2]);
        d = vec4(d[0], d[1], newVal, d[2]);
    } else if (newVal < d[3]) {
        i = ivec4(i[0], i[1], i[2], newID);
        d = vec4(d[0], d[1], d[2], newVal);
    }
}

// Returns the 4 IDs stored in the *previous* frame of Buffer B at coords c
ivec4 getClosestPrev(ivec2 c) {
    return ivec4(texelFetch(iChannel1, c, 0));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 c = ivec2(fragCoord);

    // We'll build a new set of 4 IDs
    ivec4 newIDs  = ivec4(-1);
    vec4  newVals = vec4(1e20);

    // 1) Gather from a 3x3 block around c
    for (int dy = -1; dy <= 1; dy++){
        for (int dx = -1; dx <= 1; dx++){
            ivec2 cc = wrapCoords(c + ivec2(dx, dy));
            // read the 4 IDs from the previous frame
            ivec4 four = getClosestPrev(cc);
            // insertion-sort them into newIDs using pixel-center (vec2(c)+0.5)
            for (int i = 0; i < 4; i++){
                int cand = four[i];
                float val = measureParticle(cand, vec2(c) + 0.5);
                insertion_sort(newIDs, newVals, cand, val);
            }
        }
    }

    // 2) Add a random candidate to avoid local minima
    float h = hash(
        c.x + c.y * int(iResolution.x)
        + iFrame * int(iResolution.x * iResolution.y)
    );
    int rID = int(h * float(PARTICLES));
    float rVal = measureParticle(rID, vec2(c) + 0.5);
    insertion_sort(newIDs, newVals, rID, rVal);

    // 3) Output the top 4 IDs
    fragColor = vec4(newIDs);
}

// --------------------------------------------------------
// BUFFER C
// --------------------------------------------------------
// iChannel0 => Buffer A (positions)
// iChannel1 => Buffer B (nearest neighbor IDs)
// iChannel2 => (backbuffer for C if needed, or not used?)
// iChannel3 => Buffer D (radii) <--- we fetch radius
//
// We store in .x the "bestDist" to the nearest other site
// but now we do Minkowski offset by subtracting both radii.

ivec2 locFromID(int id)
{
    int w = int(iResolution.x);
    return ivec2(id % w, id / w);
}

vec4 getParticle(int id)
{
    return texelFetch(iChannel0, locFromID(id), 0);
}

// fetch radius from Buffer D
float getRadius(int id)
{
    return texelFetch(iChannel3, locFromID(id), 0).r;
}

// Helper for wrapping distances in a toroidal domain
vec2 periodicDelta(vec2 v)
{
    return mod(v + 0.5*iResolution.xy, iResolution.xy) - 0.5*iResolution.xy;
}

// We'll read from Buffer B at integer coords.
ivec4 getClosest4(ivec2 c)
{
    // clamp or wrap c if needed
    ivec2 res = ivec2(iResolution.xy);
    c = ivec2((c.x + res.x) % res.x, (c.y + res.y) % res.y);
    return ivec4(texelFetch(iChannel1, c, 0));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 coord = ivec2(fragCoord);
    int id = coord.x + coord.y * int(iResolution.x);

    // If not a valid particle
    if(id >= PARTICLES)
    {
        fragColor = vec4(0.0);
        return;
    }

    // 1) read this particle's pos & radius
    vec2 pos   = getParticle(id).xy;
    float radA = getRadius(id);

    // 2) find the closest other site
    float bestDist = 1e20;

    // We'll read a 3x3 block in B around floor(pos)
    ivec2 base = ivec2(floor(pos));
    for(int dy=-1; dy<=1; dy++){
        for(int dx=-1; dx<=1; dx++){
            ivec2 sampleCoords = base + ivec2(dx, dy);
            ivec4 nb = getClosest4(sampleCoords);
            for(int i=0; i<4; i++){
                int nid = nb[i];
                if(nid == id || nid < 0) continue;

                vec2  otherPos = getParticle(nid).xy;
                float radB     = getRadius(nid);
                vec2 d  = periodicDelta(pos - otherPos);
                float dist     = length(d);
                float effDist  = dist - (radA + radB); // Minkowski offset

                if(effDist < bestDist){
                    bestDist = effDist;
                }
            }
        }
    }

    fragColor = vec4(bestDist, 0.0, 0.0, 1.0);
}

// --------------------------------------------------------
// BUFFER D
// --------------------------------------------------------
// This buffer holds the radius for each particle.
// iChannel0 => Buffer D (feedback/backbuffer)

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 c  = ivec2(fragCoord);
    int   id = c.x + c.y * int(iResolution.x);

    // If outside [0..PARTICLES), store 0
    if (id >= PARTICLES)
    {
        fragColor = vec4(0.0);
        return;
    }

    if(iFrame == 0)
    {
        //--------------------------------------------------
        // 1) Compute a scale factor based on how big
        //    the current resolution is vs. your "base" res:
        //--------------------------------------------------
        // Pick the resolution that you originally used and liked:
        float baseW = 1280.0;  // Example
        float baseH = 720.0;
        float baseArea = baseW * baseH;
        float newArea  = iResolution.x * iResolution.y;
        float scale    = sqrt(newArea / baseArea);

        //--------------------------------------------------
        // 2) Generate random radius in [7..26], then scale it:
        //--------------------------------------------------
        float h   = hash(id + 1234567);
        float rad = mix(7.0, 32.0, h) * scale;

        fragColor = vec4(rad, 0.0, 0.0, 1.0);
    }
    else
    {
        // keep the same radius from the previous frame
        fragColor = texelFetch(iChannel0, c, 0);
    }
}
